CREATE PROCEDURE #Lib_CheckStock @CopyNo int
AS
    IF @CopyNo > 100
        RETURN 1;    -- 非 0 表示查無資料
    RETURN 0;
GO
DECLARE @ret int;
EXEC @ret = #Lib_CheckStock @CopyNo = 999;
SELECT @ret AS ReturnCode;   -- 結果：1
GO

CREATE PROCEDURE #Lib_ListBranches
AS
    SELECT v.Branch FROM (VALUES ('A01'), ('B02')) AS v(Branch);
GO
DECLARE @t TABLE (Branch varchar(10));
INSERT INTO @t EXEC #Lib_ListBranches;
SELECT COUNT(*) AS BranchCount FROM @t;   -- 結果：2
GO

