DECLARE @Target TABLE (CopyNo int PRIMARY KEY, Branch varchar(10));
DECLARE @Source TABLE (CopyNo int, Branch varchar(10));
INSERT INTO @Target VALUES (1, 'A01');
INSERT INTO @Source VALUES (1, 'B02'), (2, 'B02');
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN MATCHED THEN UPDATE SET t.Branch = s.Branch
WHEN NOT MATCHED BY TARGET THEN INSERT (CopyNo, Branch) VALUES (s.CopyNo, s.Branch)
OUTPUT $action, inserted.CopyNo, deleted.Branch;   -- 結果：'UPDATE'(1)、'INSERT'(2)
GO

DECLARE @Target TABLE (CopyNo int PRIMARY KEY);
DECLARE @Source TABLE (CopyNo int);
INSERT INTO @Target VALUES (1), (2);
INSERT INTO @Source VALUES (1);
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN NOT MATCHED BY SOURCE THEN DELETE;
SELECT * FROM @Target;   -- 結果：只剩 CopyNo = 1
GO

DECLARE @Target TABLE (CopyNo int PRIMARY KEY, Branch varchar(10));
DECLARE @Source TABLE (CopyNo int, Branch varchar(10));
INSERT INTO @Target VALUES (1, 'A01');
INSERT INTO @Source VALUES (1, 'B02'), (1, 'B03');   -- 同一個 CopyNo 出現兩次
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN MATCHED THEN UPDATE SET t.Branch = s.Branch;
-- 結果：執行期錯誤，同一列被 MERGE 嘗試更新兩次
GO

